package custody

import (
	"bytes"
	"encoding/binary"
	"os"
	"reflect"
	"testing"

	"filippo.io/age"
)

// This binary was captured from signed61d9682a's unmodified v1 encoder on
// kvm003 before the v2 change. It must never be regenerated by the v2 writer.
func legacyBootstrapFixture(t *testing.T) (SecretBinding, EffectiveBootstrap, []byte) {
	t.Helper()
	binding := SecretBinding{ClusterUID: "legacy-cluster", ProjectUID: "legacy-project", ResourceUID: "legacy-resource", OperationID: "legacy-operation", PayloadID: "legacy-payload", AdmittedGeneration: 19}
	files := EffectiveBootstrap{UserData: []byte("v1-user\r\n\x00\xff"), Metadata: []byte("instance-id: legacy-resource\r\nlocal-hostname: legacy\r\n"), NetworkConfig: []byte{}}
	frame, err := os.ReadFile("testdata/effective_bootstrap_v1.bin")
	if err != nil {
		t.Fatal("static legacy frame unavailable")
	}
	return binding, files, frame
}

func TestAutomationSecretVendorRoundTrip(t *testing.T) {
	binding := secretBindingFixture()
	id := secretIdentity(t)
	for _, vendor := range [][]byte{nil, {}, []byte("VENDOR-PRIVATE\x00\xff\r\n")} {
		files := EffectiveBootstrap{UserData: []byte{}, Metadata: []byte("m\r\n"), NetworkConfig: []byte{}, VendorData: vendor}
		cipher, err := EncryptBootstrap(binding, files, []*age.X25519Recipient{id.Recipient()})
		if err != nil {
			t.Fatal("four-file encryption failed")
		}
		got, err := DecryptBootstrap(binding, cipher, []*age.X25519Identity{id})
		if err != nil || !reflect.DeepEqual(got, files) {
			t.Error("four-file ciphertext lost vendor bytes or presence")
		}
	}
}

func TestAutomationSecretVendorLegacyV1(t *testing.T) {
	binding, files, frame := legacyBootstrapFixture(t)
	if binary.BigEndian.Uint32(frame[len(effectiveBootstrapDomain):]) != 1 {
		t.Fatal("fixture is not actual version1")
	}
	id := secretIdentity(t)
	cipher := encryptRawBootstrap(t, frame, id.Recipient())
	got, err := DecryptBootstrap(binding, cipher, []*age.X25519Identity{id})
	if err != nil || !reflect.DeepEqual(got, files) || got.VendorData != nil {
		t.Fatal("actual old frame was reinterpreted")
	}
	// v1 has exactly three files; an added absent vendor frame is trailing data.
	for _, bad := range [][]byte{append(bytes.Clone(frame), 0), append(bytes.Clone(frame), 0, 0, 0, 0, 0)} {
		got, err := decodeBootstrap(binding, bad)
		requireNoBootstrap(t, got, err)
	}
}

func TestAutomationSecretVendorVersionFraming(t *testing.T) {
	binding := secretBindingFixture()
	files := EffectiveBootstrap{UserData: []byte{}, Metadata: []byte("m"), NetworkConfig: nil, VendorData: []byte("vendor")}
	frame, err := encodeBootstrap(binding, files)
	if err != nil {
		t.Fatal("v2 frame creation failed")
	}
	if binary.BigEndian.Uint32(frame[len(effectiveBootstrapDomain):]) != 2 {
		t.Fatal("new encoding did not select version2")
	}
	for _, version := range []uint32{0, 3, 0xffffffff} {
		bad := bytes.Clone(frame)
		binary.BigEndian.PutUint32(bad[len(effectiveBootstrapDomain):], version)
		got, err := decodeBootstrap(binding, bad)
		requireNoBootstrap(t, got, err)
	}
	vendorOffset := len(frame) - 5 - len(files.VendorData)
	for _, present := range []byte{0, 2} {
		bad := bytes.Clone(frame)
		bad[vendorOffset] = present
		got, err := decodeBootstrap(binding, bad)
		requireNoBootstrap(t, got, err)
	}
	bad := bytes.Clone(frame)
	binary.BigEndian.PutUint32(bad[vendorOffset+1:], 0xffffffff)
	got, err := decodeBootstrap(binding, bad)
	requireNoBootstrap(t, got, err)
	for _, cut := range []int{vendorOffset, vendorOffset + 1, len(frame) - 1} {
		got, err := decodeBootstrap(binding, frame[:cut])
		requireNoBootstrap(t, got, err)
	}
	got, err = decodeBootstrap(binding, append(bytes.Clone(frame), 0))
	requireNoBootstrap(t, got, err)
	empty, err := encodeBootstrap(binding, EffectiveBootstrap{VendorData: []byte{}})
	if err != nil {
		t.Fatal("vendor budget setup failed")
	}
	exact := EffectiveBootstrap{VendorData: make([]byte, bootstrapPlaintextMaxBytes-len(empty))}
	b, err := encodeBootstrap(binding, exact)
	if err != nil || len(b) != bootstrapPlaintextMaxBytes {
		t.Fatal("four-file aggregate cap not enforced exactly")
	}
	exact.UserData = []byte{0}
	if b, err := encodeBootstrap(binding, exact); err == nil || b != nil {
		t.Fatal("four-file aggregate overflow accepted")
	}
}

func TestAutomationSecretVendorRewrapPreservesOriginAndReceipt(t *testing.T) {
	binding, files, oldFrame := legacyBootstrapFixture(t)
	a, b := secretIdentity(t), secretIdentity(t)
	key, err := NewBootstrapEqualityKey("original-epoch", bytes.Repeat([]byte{42}, 32))
	if err != nil {
		t.Fatal("equality setup failed")
	}
	scope := IntentScope{ClusterUID: binding.ClusterUID, Namespace: "namespace", Method: "create"}
	raw := RawBootstrapIntent{Present: true, UserData: []byte{}, NetworkConfig: []byte{}}
	tag, err := key.IntentTag("original-epoch", scope, raw)
	if err != nil {
		t.Fatal("receipt setup failed")
	}
	oldCipher := encryptRawBootstrap(t, oldFrame, a.Recipient())
	saved := bytes.Clone(oldCipher)
	recovered, err := DecryptBootstrap(binding, oldCipher, []*age.X25519Identity{a})
	if err != nil {
		t.Fatal("old decrypt failed")
	}
	replacement, err := EncryptBootstrap(binding, recovered, []*age.X25519Recipient{b.Recipient()})
	if err != nil {
		t.Fatal("legacy rewrap failed")
	}
	got, err := DecryptBootstrap(binding, replacement, []*age.X25519Identity{b})
	if err != nil || !reflect.DeepEqual(got, files) {
		t.Fatal("legacy semantic files changed on rewrap")
	}
	if !bytes.Equal(oldCipher, saved) {
		t.Fatal("original ciphertext changed")
	}
	wrong := binding
	wrong.AdmittedGeneration++
	got, err = DecryptBootstrap(wrong, replacement, []*age.X25519Identity{b})
	requireNoBootstrap(t, got, err)
	// Generated vendor bytes are effective files, not a fourth raw caller field.
	files.VendorData = []byte("generated-vendor\r\n")
	replacement, err = EncryptBootstrap(binding, files, []*age.X25519Recipient{b.Recipient()})
	if err != nil {
		t.Fatal("vendor encryption failed")
	}
	got, err = DecryptBootstrap(binding, replacement, []*age.X25519Identity{b})
	if err != nil || !reflect.DeepEqual(got, files) {
		t.Fatal("vendor rewrap files changed")
	}
	equal, err := key.CompareIntent("original-epoch", scope, raw, tag)
	if err != nil || !equal {
		t.Fatal("effective wrapping changed original equality receipt")
	}
}
